<?php
/** @var \App\Moderation\SocialReport $report */
$date = static function (?string $value): string { if ($value === null) { return '—'; } try { return (new DateTimeImmutable($value))->format('d/m/Y H:i'); } catch (Throwable) { return $value; } };
?>
<section class="admin-report" aria-labelledby="admin-report-title">
    <?php foreach (($messages['success'] ?? []) as $message): ?><p class="form-alert form-alert--success" role="status"><?= e((string) $message) ?></p><?php endforeach; ?>
    <a class="report-page__back" href="/admin/denuncias">← Voltar à fila</a>
    <header class="admin-report__header"><div><p class="eyebrow">Moderação · denúncia #<?= $report->id ?></p><h1 id="admin-report-title"><?= e($report->targetType->label()) ?> denunciado</h1></div><span class="report-status report-status--<?= e($report->status->value) ?>"><?= e($report->status->label()) ?></span></header>
    <div class="admin-report__grid">
        <section class="admin-report__panel"><h2>Registro</h2><dl><div><dt>Motivo</dt><dd><?= e($report->reason->label()) ?></dd></div><div><dt>Reporter</dt><dd>@<?= e($report->reporterUsername) ?></dd></div><div><dt>Usuário denunciado</dt><dd><?= e($report->targetDisplayName ?? 'Indisponível') ?><?= $report->targetUsername !== null ? ' · @' . e($report->targetUsername) : '' ?></dd></div><div><dt>Enviada em</dt><dd><?= e($date($report->createdAt)) ?></dd></div></dl></section>
        <section class="admin-report__panel"><h2>Detalhes fornecidos</h2><p class="admin-report__text"><?= $report->details !== null ? nl2br(e($report->details)) : 'Nenhum detalhe adicional.' ?></p></section>
        <section class="admin-report__panel admin-report__panel--snapshot"><h2>Snapshot preservado</h2><p class="admin-report__text"><?= $report->contentSnapshot !== null && $report->contentSnapshot !== '' ? nl2br(e($report->contentSnapshot)) : 'O alvo não possuía texto no momento da denúncia.' ?></p></section>
        <?php if ($report->status !== \App\Moderation\ReportStatus::Pending): ?><section class="admin-report__panel"><h2>Revisão encerrada</h2><dl><div><dt>Data</dt><dd><?= e($date($report->reviewedAt)) ?></dd></div><div><dt>Nota interna</dt><dd><?= $report->moderatorNote !== null ? nl2br(e($report->moderatorNote)) : 'Sem nota.' ?></dd></div></dl></section><?php endif; ?>
    </div>
    <?php if ($report->status === \App\Moderation\ReportStatus::Pending): ?><section class="admin-review" aria-labelledby="admin-review-title"><p class="eyebrow">Decisão administrativa</p><h2 id="admin-review-title">Encerrar revisão</h2><p>Classifique a denúncia. Esta ação não remove conteúdo nem aplica sanções.</p><form method="post" novalidate><?= $csrf->field() ?><div class="profile-field"><label for="moderator-note">Nota interna <span>(opcional)</span></label><textarea id="moderator-note" name="moderator_note" rows="6" maxlength="1000" aria-describedby="moderator-note-hint<?= isset($errors['moderator_note']) ? ' moderator-note-error' : '' ?>"<?= isset($errors['moderator_note']) ? ' aria-invalid="true"' : '' ?>><?= e($note) ?></textarea><p id="moderator-note-hint">Visível somente na área administrativa. Até 1000 caracteres.</p><?php if (isset($errors['moderator_note'])): ?><p class="profile-field__error" id="moderator-note-error" role="alert"><?= e((string) $errors['moderator_note']) ?></p><?php endif; ?></div><div class="admin-review__actions"><button class="button button--primary" type="submit" formaction="/admin/denuncias/<?= $report->id ?>/resolver">Marcar como resolvida</button><button class="button button--secondary" type="submit" formaction="/admin/denuncias/<?= $report->id ?>/arquivar">Arquivar denúncia</button></div></form></section><?php endif; ?>
</section>
